import java.io.*;

public class Main {
    private static final int BUF_SIZE = 1 << 16;
    private static final byte[] buf = new byte[BUF_SIZE];
    private static int bufLen = 0, bufPos = 0;
    private static final InputStream in = System.in;

    private static int readByte() throws IOException {
        if (bufPos == bufLen) {
            bufLen = in.read(buf, 0, BUF_SIZE);
            bufPos = 0;
            if (bufLen <= 0) return -1;
        }
        return buf[bufPos++];
    }

    private static int nextInt() throws IOException {
        int b = readByte();
        while (b != -1 && (b < '0' || b > '9')) b = readByte();
        int ret = 0;
        while (b >= '0' && b <= '9') {
            ret = ret * 10 + (b - '0');
            b = readByte();
        }
        return ret;
    }

    public static void main(String[] args) throws IOException {
        int E = nextInt();
        int M = nextInt();
        int D = nextInt();

        int totalPairs = M + D;
        int[] pairA = new int[totalPairs];
        int[] pairB = new int[totalPairs];

        // Primeiras M posições: pares "juntos"; próximas D: pares "separados"
        for (int i = 0; i < totalPairs; i++) {
            pairA[i] = nextInt();
            pairB[i] = nextInt();
        }

        int[] group = new int[E + 1];
        int g = 0;
        for (int i = 0; i < E / 3; i++, g++) {
            int a = nextInt();
            int b = nextInt();
            int c = nextInt();
            group[a] = g;
            group[b] = g;
            group[c] = g;
        }

        int violations = 0;
        // Par que queria estar junto: viola se grupos diferem
        for (int i = 0; i < M; i++) {
            if (group[pairA[i]] != group[pairB[i]]) violations++;
        }
        // Par que queria estar separado: viola se grupos iguais
        for (int i = M; i < totalPairs; i++) {
            if (group[pairA[i]] == group[pairB[i]]) violations++;
        }

        StringBuilder sb = new StringBuilder();
        sb.append(violations).append('\n');
        System.out.print(sb);
    }
}
